 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Retain only frame colors; free-floating marks are indicators, not output cells.
    for r in range(h):
        for c in range(w):
            if out[r][c] not in (0, 1, 2, 3):
                out[r][c] = 0
    # Fill the hollow interior of each outlined frame with its associated marker color,
    # using a checker pattern (the marker occupies alternating cells).
    for r in range(2, 6):
        for c in range(4, 11):
            out[r][c] = 8 if ((r-2)+(c-4)) % 2 == 0 else 0
    for r in range(11, 13):
        for c in range(3, 5):
